import fs from 'fs';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
const tok = JSON.parse(fs.readFileSync('<scratch>','utf8')).token;
const [tool, argsJson] = [process.argv[2], process.argv[3]||'{}'];
const t = new StreamableHTTPClientTransport(new URL('http://192.168.31.145:8799/mcp'), {requestInit:{headers:{Authorization:'Bearer '+tok}}});
const c = new Client({name:'ana',version:'1'});
await c.connect(t);
if (tool==='__list') { const r = await c.listTools(); console.log(JSON.stringify(r.tools.map(x=>({n:x.name,d:x.description})),null,1)); }
else { const r = await c.callTool({name:tool, arguments: JSON.parse(argsJson)}); console.log(r.content.map(x=>x.text).join('\n')); }
await c.close();
EOF
